"""Read-only community discovery and evidence index; never execute inherited code."""
import json
import os
from pathlib import Path
import subprocess

Q = Path(__file__).resolve().parents[1]
OUT = Q / 'inputs' / 'prior'
OUT.mkdir(parents=True, exist_ok=True)
LIB = Path(os.environ['BIO_COMMUNITY']) / 'library'

def cli(args, label):
    result = subprocess.run(['./bin/bio', *args], capture_output=True, text=True, check=True)
    (OUT / f'{label}.json').write_text(result.stdout)
    return json.loads(result.stdout)

queries = ['miR-29', 'IRE1', 'AGO2', 'Dicer', 'G3BP', 'RNA stability', 'ribosome', 'GSE103957', 'PMP22']
for n, term in enumerate(queries):
    result = cli(['community', 'search', '--text', term, '--limit', '100'], f'forum-{n}')
    print(term, 'total=', result['total'], 'next=', result.get('next_offset'))
    for item in result['items']:
        print(' ', item['subject'], item['title'], 'superseded=', item.get('superseded_by'))
for command in ['artifact', 'work', 'data']:
    result = cli(['--workspace', str(LIB), command, 'search', '--text', 'RNA'], f'library-{command}')
    print('LIBRARY', command, result.get('total'))
    for item in result.get('items', []):
        print(' ', item.get('subject'), item.get('title'))
for h, label in [('e054cae33492c105e41221766e86dc067d7c5dfeaf75fc8409c23b468964166b', 'notebook-manifest'), ('ec40eba9a7bdd48c792a6163e7a40a9e4105cdc5aadc492977bbaf42f9eea2a3', 'prior-package'), ('043b8a66d39ab07ff0ad7ad179e3d13e36e6c88f5b480d4f3d25f6e43ebe287e', 'mechanism-map')]:
    p = LIB / 'blobs' / 'sha256' / h[:2] / h
    data = json.loads(p.read_text())
    (OUT / f'{label}.json').write_text(json.dumps(data, indent=2))
    print(label, 'keys=', list(data))
    if label == 'mechanism-map':
        for edge in data['edges']:
            if any(word in json.dumps(edge).lower() for word in ['mir', 'ire1', 'g3bp', 'dicer', 'footprint']):
                print(json.dumps(edge, indent=2))
    if label == 'prior-package':
        print(json.dumps(data, indent=2)[:6500])

"""Locate published immutable sources by manifest; copy only selected readable evidence."""
import hashlib
import json
import os
from pathlib import Path

Q = Path(__file__).resolve().parents[1]
LIB = Path(os.environ['BIO_COMMUNITY']) / 'library' / 'blobs' / 'sha256'

def load(h):
    return json.loads((LIB / h[:2] / h).read_text())

def walk(x):
    if isinstance(x, dict):
        yield x
        for v in x.values():
            yield from walk(v)
    elif isinstance(x, list):
        for v in x:
            yield from walk(v)

hashes = ['eebf29a5ebae3ce0fba441f460140d106ae3734bb491d4c35768b64d881f170f', '23f94e75dab1ce2b57cda1ca09d1552867e8608357dd04e88572f0bcdbe907bf', '64c4b850716399cd6d4ace83150146a127950c2c41c8480bd5237501d8a13656']
terms = ['2713384', '6920087', '2728407', '3866477', 'context-audit', '11014456', '5800313', '11592338']
selected = []
for manifest in hashes:
    data = load(manifest)
    print('MANIFEST', manifest, list(data))
    (Q / 'inputs' / 'prior' / f'{manifest}.json').write_text(json.dumps(data, indent=2))
    for d in walk(data):
        fields = {k: v for k, v in d.items() if isinstance(v, (str, int))}
        if any(t in str(fields) for t in terms):
            print(fields)
            selected.append({'manifest': manifest, **fields})
(Q / 'inputs' / 'prior' / 'source-candidates.json').write_text(json.dumps(selected, indent=2))
print('Candidates', len(selected))

"""Render BioC source passages and inspect primary-source locators without execution."""
from pathlib import Path
from xml.etree import ElementTree as ET

q = Path(__file__).resolve().parents[1]
for p in (q / 'inputs' / 'primary').glob('*-bioc.source'):
    root = ET.fromstring(p.read_bytes())
    parts = []
    for e in root.findall('.//passage'):
        meta = {i.get('key'): i.text for i in e.findall('infon')}
        parts.append('[' + str(meta) + ' offset=' + str(e.findtext('offset')) + ']\n' + str(e.findtext('text')))
    p.with_suffix('.txt').write_text('\n\n'.join(parts))
    print(p.name, 'passages', len(parts), 'first', parts[:2])
for name in ['PMC13431160', 'PMC9852534', 'PMC3002990', 'PMC11784151']:
    root = ET.fromstring((q / 'inputs' / 'primary' / (name + '.source')).read_bytes())
    print(name, 'TITLE', root.findtext('.//article-title'))
    if name == 'PMC13431160':
        for e in root.iter('p'):
            t = ' '.join(''.join(e.itertext()).split())
            if any(k in t for k in ['GSE', 'SLAM', 'degradation rate', 'PMP22', 'Pmp22', '4sU', 'half-life']):
                print(t)

